# relay-loop project config (sourced by bash). Generated by `relay init`; edit freely.

PROJECT_NAME="__NAME__"

# One line per git repo: "name|path relative to this project|executor|check command"
#   executor = claude  → Claude passes write the code themselves (backend, scripts, anything)
#   executor = agy     → Antigravity writes the UI; Claude writes its prompts and reviews (max one repo)
REPOS=(
__REPOS__
)

# branch = agents work in git worktrees on a loop/<date> branch under ~/.relay-loop/work/<project>;
#          the runner commits each pass's reviewed (staged) work there. Your checkout is untouched.
# stage  = agents work in your own checkout and leave reviewed work staged. Nothing is committed.
MODE=branch
WORKTREE_LINK=(node_modules)   # untracked paths symlinked from your checkout into each worktree

MAX_PASSES=12
WEEK_STOP=80       # stop when weekly usage reaches this %
SESSION_STOP=85    # pause 30 min when the 5-hour session reaches this %
GAP_SECONDS=300
CLAUDE_EFFORT=medium
AGY_MODEL=gemini-4-argon-high
AGY_TIMEOUT=45m

# Extra tools Claude passes may never use, e.g. "Bash(npm run dev:*)" "Bash(psql:*)"
EXTRA_DENY=(__DENY__)
# Extra Antigravity allow-rules (prefix match), e.g. "command(npx prettier)"
AGY_EXTRA_ALLOW=()
# Optional: a command that receives one message argument when the loop stops (ntfy, Slack webhook...)
NOTIFY_CMD=""

# What must never happen in this project. Every pass reads this. relay init lists what it detected;
# check it, add what it can't know (prod data, money, customers), then set HAZARDS_REVIEWED=yes.
HAZARDS="
__HAZARDS__
"
HAZARDS_REVIEWED=no
